--136 expands only the compiled own-account export projection. No Privacy text,
--retention rule, lifetime, policy admission or live activation is seeded.
begin;
set local lock_timeout='5s';set local statement_timeout='30s';
do $pre$ begin
if (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid='private.data_export_dataset_catalog()'::regprocedure)<>'b5acea18506b83c81286cfd0b6799ad3' then raise exception 'V5_EXPORT_PREDECESSOR_DRIFT' using detail='data_export_dataset_catalog';end if;
if (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid='private.data_export_policy_binding()'::regprocedure)<>'bf1163414f20cd9965321b59b2f4fa01' then raise exception 'V5_EXPORT_PREDECESSOR_DRIFT' using detail='data_export_policy_binding';end if;
if (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid='private.data_export_snapshot(uuid,uuid,jsonb,timestamptz)'::regprocedure)<>'09ba3c6d468e2a702bfff39428715b3f' then raise exception 'V5_EXPORT_PREDECESSOR_DRIFT' using detail='data_export_snapshot';end if;
if to_regclass('private.qa_ai_commands') is null then raise exception 'V5_EXPORT_SOURCE135_REQUIRED';end if;
end $pre$;
create function private.data_export_scalar_v5(v jsonb,t text) returns jsonb language sql immutable set search_path=pg_catalog as $f$ select case when jsonb_typeof(v)=t and t in('string','number','boolean') then v else 'null'::jsonb end $f$;
create function private.data_export_array_v5(v jsonb,t text) returns jsonb language sql immutable set search_path=pg_catalog as $f$ select coalesce(jsonb_agg(x order by ordinal),'[]'::jsonb) from jsonb_array_elements(case when jsonb_typeof(v)='array' then v else '[]'::jsonb end) with ordinality a(x,ordinal) where jsonb_typeof(x)=t and t in('string','number','boolean') $f$;
create function private.data_export_worker_candidate_v5(v jsonb) returns jsonb language sql immutable set search_path=pg_catalog as $f$ select jsonb_build_object('displayName',private.data_export_scalar_v5(v->'displayName','string'),'bio',private.data_export_scalar_v5(v->'bio','string'),'skills',private.data_export_array_v5(v->'skills','string'),'tools',private.data_export_array_v5(v->'tools','string'),'licenses',private.data_export_array_v5(v->'licenses','string'),'vehicles',private.data_export_array_v5(v->'vehicles','string'),'teamCapacity',private.data_export_scalar_v5(v->'teamCapacity','number'),'location',jsonb_build_object('operatingCountryCode',private.data_export_scalar_v5(v#>'{location,operatingCountryCode}','string'),'city',private.data_export_scalar_v5(v#>'{location,city}','string'),'radiusKm',private.data_export_scalar_v5(v#>'{location,radiusKm}','number'),'approximatePosition',jsonb_build_object('latitude',private.data_export_scalar_v5(v#>'{location,approximatePosition,latitude}','number'),'longitude',private.data_export_scalar_v5(v#>'{location,approximatePosition,longitude}','number'))),'availability',jsonb_build_object('timezone',private.data_export_scalar_v5(v#>'{availability,timezone}','string'),'availableNow',private.data_export_scalar_v5(v#>'{availability,availableNow}','boolean'),'rules',coalesce((select jsonb_agg(jsonb_build_object('id',private.data_export_scalar_v5(x->'id','string'),'startTime',private.data_export_scalar_v5(x->'startTime','string'),'endTime',private.data_export_scalar_v5(x->'endTime','string'),'startsOn',private.data_export_scalar_v5(x->'startsOn','string'),'endsOn',private.data_export_scalar_v5(x->'endsOn','string'),'label',private.data_export_scalar_v5(x->'label','string'),'active',private.data_export_scalar_v5(x->'active','boolean'),'weekdays',private.data_export_array_v5(x->'weekdays','number')) order by ordinal) from jsonb_array_elements(case when jsonb_typeof(v#>'{availability,rules}')='array' then v#>'{availability,rules}' else '[]'::jsonb end) with ordinality as a(x,ordinal) where jsonb_typeof(x)='object'),'[]'::jsonb),'windows',coalesce((select jsonb_agg(jsonb_build_object('id',private.data_export_scalar_v5(x->'id','string'),'startsAt',private.data_export_scalar_v5(x->'startsAt','string'),'endsAt',private.data_export_scalar_v5(x->'endsAt','string'),'state',private.data_export_scalar_v5(x->'state','string'),'label',private.data_export_scalar_v5(x->'label','string')) order by ordinal) from jsonb_array_elements(case when jsonb_typeof(v#>'{availability,windows}')='array' then v#>'{availability,windows}' else '[]'::jsonb end) with ordinality as a(x,ordinal) where jsonb_typeof(x)='object'),'[]'::jsonb))) $f$;
create function private.data_export_task_facts_v5(v jsonb) returns jsonb language sql immutable set search_path=pg_catalog as $f$ select coalesce(jsonb_agg(jsonb_build_object('key',x->>'key','value',case x->>'key' when 'need.title' then private.data_export_scalar_v5(x->'value','string') when 'need.description' then private.data_export_scalar_v5(x->'value','string') when 'need.category' then private.data_export_scalar_v5(x->'value','string') when 'need.price_mode' then private.data_export_scalar_v5(x->'value','string') when 'need.price_rsd' then private.data_export_scalar_v5(x->'value','number') when 'need.schedule_kind' then private.data_export_scalar_v5(x->'value','string') when 'need.starts_at' then private.data_export_scalar_v5(x->'value','string') when 'need.ends_at' then private.data_export_scalar_v5(x->'value','string') when 'need.people_needed' then private.data_export_scalar_v5(x->'value','number') when 'need.required_skills' then private.data_export_array_v5(x->'value','string') when 'need.required_tools' then private.data_export_array_v5(x->'value','string') when 'need.required_vehicles' then private.data_export_array_v5(x->'value','string') when 'need.required_licenses' then private.data_export_array_v5(x->'value','string') when 'need.minimum_experience_years' then private.data_export_scalar_v5(x->'value','number') when 'need.verified_identity_required' then private.data_export_scalar_v5(x->'value','boolean') when 'need.task_country_code' then private.data_export_scalar_v5(x->'value','string') when 'need.task_geography' then jsonb_build_object('mode',private.data_export_scalar_v5((x->'value')->'mode','string'),'start',jsonb_build_object('label',private.data_export_scalar_v5((x->'value')->'start'->'label','string'),'city',private.data_export_scalar_v5((x->'value')->'start'->'city','string'),'area',private.data_export_scalar_v5((x->'value')->'start'->'area','string')),'end',jsonb_build_object('label',private.data_export_scalar_v5((x->'value')->'end'->'label','string'),'city',private.data_export_scalar_v5((x->'value')->'end'->'city','string'),'area',private.data_export_scalar_v5((x->'value')->'end'->'area','string')),'serviceArea',jsonb_build_object('label',private.data_export_scalar_v5((x->'value')->'serviceArea'->'label','string'),'city',private.data_export_scalar_v5((x->'value')->'serviceArea'->'city','string'),'area',private.data_export_scalar_v5((x->'value')->'serviceArea'->'area','string')),'waypoints',coalesce((select jsonb_agg(jsonb_build_object('label',private.data_export_scalar_v5(x->'label','string'),'city',private.data_export_scalar_v5(x->'city','string'),'area',private.data_export_scalar_v5(x->'area','string')) order by ordinal) from jsonb_array_elements(case when jsonb_typeof((x->'value')->'waypoints')='array' then (x->'value')->'waypoints' else '[]'::jsonb end) with ordinality as a(x,ordinal) where jsonb_typeof(x)='object'),'[]'::jsonb)) when 'need.critical_conditions' then private.data_export_array_v5(x->'value','string') when 'need.public_photo_paths' then private.data_export_array_v5(x->'value','string') when 'need.exact_address' then private.data_export_scalar_v5(x->'value','string') when 'need.access_notes' then private.data_export_scalar_v5(x->'value','string') when 'need.resolved_location' then jsonb_build_object('points',coalesce((select jsonb_agg(jsonb_build_object('slot',private.data_export_scalar_v5(x->'slot','string'),'address',private.data_export_scalar_v5(x->'address','string'),'accessNotes',private.data_export_scalar_v5(x->'accessNotes','string'),'latitudeE6',private.data_export_scalar_v5(x->'latitudeE6','number'),'longitudeE6',private.data_export_scalar_v5(x->'longitudeE6','number')) order by ordinal) from jsonb_array_elements(case when jsonb_typeof(x#>'{value,points}')='array' then x#>'{value,points}' else '[]'::jsonb end) with ordinality as a(x,ordinal) where jsonb_typeof(x)='object'),'[]'::jsonb)) else null end,'displayValue',private.data_export_scalar_v5(x->'displayValue','string'),'status',private.data_export_scalar_v5(x->'status','string')) order by x->>'key'),'[]'::jsonb) from jsonb_array_elements(case when jsonb_typeof(v)='array' then v else '[]'::jsonb end) a(x) where jsonb_typeof(x)='object' and x->>'key' in('need.title','need.description','need.category','need.price_mode','need.price_rsd','need.schedule_kind','need.starts_at','need.ends_at','need.people_needed','need.required_skills','need.required_tools','need.required_vehicles','need.required_licenses','need.minimum_experience_years','need.verified_identity_required','need.task_country_code','need.task_geography','need.critical_conditions','need.public_photo_paths','need.exact_address','need.access_notes','need.resolved_location') $f$;
revoke all on function private.data_export_scalar_v5(jsonb,text),private.data_export_array_v5(jsonb,text),private.data_export_worker_candidate_v5(jsonb),private.data_export_task_facts_v5(jsonb) from public,anon,authenticated,service_role;
create or replace function private.data_export_dataset_catalog() returns jsonb language sql immutable security definer set search_path=pg_catalog as $fn$ select '[{"key":"account","dataClass":"ACCOUNT_IDENTITY","fields":["activeMode","city","createdAt","email","fullName","id","phone"],"ownershipFilter":"t.id=REQUEST_ACCOUNT"},{"key":"profiles","dataClass":"PROFILE_DATA","fields":["bio","city","displayName","headline","id","kind","operatingCountryCode","skills","status"],"ownershipFilter":"t.account_id=REQUEST_ACCOUNT"},{"key":"availabilityWindows","dataClass":"PROFILE_DATA","fields":["endsAt","id","label","profileId","startsAt","state"],"ownershipFilter":"p.account_id=REQUEST_ACCOUNT"},{"key":"availabilityRules","dataClass":"PROFILE_DATA","fields":["active","endTime","endsOn","id","label","profileId","startTime","startsOn","weekdays"],"ownershipFilter":"p.account_id=REQUEST_ACCOUNT"},{"key":"calendar","dataClass":"PROFILE_DATA","fields":["agreementId","endsAt","startsAt","state"],"ownershipFilter":"t.worker_account_id=REQUEST_ACCOUNT"},{"key":"needs","dataClass":"NEED_PUBLIC","fields":["countryCode","description","endsAt","executionMode","id","requiredSlots","revision","startsAt","status","timezone","title"],"ownershipFilter":"t.requester_account_id=REQUEST_ACCOUNT"},{"key":"needPrivate","dataClass":"NEED_SENSITIVE","fields":["accessNotes","exactAddress","latitude","longitude","needId","resolvedPoints"],"ownershipFilter":"n.requester_account_id=REQUEST_ACCOUNT"},{"key":"responses","dataClass":"RESPONSES_SELECTION","fields":["coveredSlots","createdAt","id","kind","message","needId","needRevision","priceRsd","scopeNote","status"],"ownershipFilter":"t.worker_account_id=REQUEST_ACCOUNT"},{"key":"ownQuestions","dataClass":"PRESELECTION_QA","fields":["createdAt","id","needId","question","status"],"ownershipFilter":"t.asker_account_id=REQUEST_ACCOUNT"},{"key":"ownAnswers","dataClass":"PRESELECTION_QA","fields":["answer","createdAt","id","questionId","version"],"ownershipFilter":"t.answered_by_account_id=REQUEST_ACCOUNT"},{"key":"agreements","dataClass":"AGREEMENT_CORE","fields":["createdAt","currentVersion","id","needId","status"],"ownershipFilter":"t.requester_account_id=REQUEST_ACCOUNT or t.worker_account_id=REQUEST_ACCOUNT"},{"key":"ownAgreementMessages","dataClass":"AGREEMENT_MESSAGES","fields":["agreementId","body","createdAt","id"],"ownershipFilter":"t.sender_account_id=REQUEST_ACCOUNT and (a.requester_account_id=REQUEST_ACCOUNT or a.worker_account_id=REQUEST_ACCOUNT)"},{"key":"consent","dataClass":"LEGAL_CONSENT","fields":["acceptedAt","id","privacySha256","privacyVersion","termsSha256","termsVersion"],"ownershipFilter":"t.account_id=REQUEST_ACCOUNT"},{"key":"notifications","dataClass":"NOTIFICATION_DELIVERY","fields":["body","channel","createdAt","id","readAt","role","state","title"],"ownershipFilter":"t.recipient_user_id=REQUEST_ACCOUNT"},{"key":"aiMessages","dataClass":"AI_VOLATILE","fields":["content","conversationId","createdAt","id","role"],"ownershipFilter":"t.account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"},{"key":"mediaMetadata","dataClass":"MEDIA_OBJECTS","fields":["bytesIncluded","createdAt","name"],"ownershipFilter":"t.bucket_id=''profile-media'' and split_part(t.name,''/'',1)=REQUEST_ACCOUNT::text"},{"key":"exportRequests","dataClass":"COMMAND_LEDGERS","fields":["completedAt","id","kind","requestedAt","status"],"ownershipFilter":"t.account_id=REQUEST_ACCOUNT"},{"key":"ownAudit","dataClass":"AUDIT_SECURITY_LOGS","fields":["createdAt","entityId","entityType","eventType","id"],"ownershipFilter":"t.actor_user_id=REQUEST_ACCOUNT"},{"key":"ownAgreementReviews","dataClass":"AGREEMENT_REVIEWS","fields":["agreementId","createdAt","id","rating","tags"],"ownershipFilter":"t.reviewer_account_id=REQUEST_ACCOUNT and (a.requester_account_id=REQUEST_ACCOUNT or a.worker_account_id=REQUEST_ACCOUNT)"},{"key":"ownSafetyReports","dataClass":"AUDIT_SECURITY_LOGS","fields":["agreementId","category","createdAt","id","narrative","needId","reason","status"],"ownershipFilter":"t.reporter_account_id=REQUEST_ACCOUNT"},{"key":"ownBlocks","dataClass":"AUDIT_SECURITY_LOGS","fields":["active","revision","targetAccountId","updatedAt"],"ownershipFilter":"t.blocker_account_id=REQUEST_ACCOUNT"},{"key":"workerAiDrafts","dataClass":"AI_VOLATILE","fields":["conversationId","createdAt","profile","profileId","revision","safety"],"ownershipFilter":"t.account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"},{"key":"workerAiReviews","dataClass":"AI_VOLATILE","fields":["activate","conversationId","createdAt","id","profile","revision"],"ownershipFilter":"t.account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"},{"key":"taskAiReviews","dataClass":"AI_VOLATILE","fields":["conversationId","createdAt","draftId","draftRevision","id","privateFacts","publicFacts","responseDeadline"],"ownershipFilter":"t.account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"},{"key":"taskAiFacts","dataClass":"AI_VOLATILE","fields":["conversationId","facts","id"],"ownershipFilter":"c.account_id=REQUEST_ACCOUNT"},{"key":"workerAiTurns","dataClass":"COMMAND_LEDGERS","fields":["conversationId","createdAt","id","state"],"ownershipFilter":"t.account_id=REQUEST_ACCOUNT"},{"key":"workerAiSaves","dataClass":"COMMAND_LEDGERS","fields":["createdAt","reviewId"],"ownershipFilter":"t.account_id=REQUEST_ACCOUNT"},{"key":"taskReviewCommands","dataClass":"COMMAND_LEDGERS","fields":["createdAt","needId","needRevision","reviewId","state"],"ownershipFilter":"t.account_id=REQUEST_ACCOUNT"},{"key":"taskAiTurns","dataClass":"COMMAND_LEDGERS","fields":["cancelledAt","conversationId","createdAt","id","state"],"ownershipFilter":"t.account_id=REQUEST_ACCOUNT"},{"key":"qaClassifications","dataClass":"COMMAND_LEDGERS","fields":["createdAt","id","materiality","needId","needRevision","outcome","questionId","state","type"],"ownershipFilter":"t.account_id=REQUEST_ACCOUNT"},{"key":"qaCommands","dataClass":"COMMAND_LEDGERS","fields":["createdAt","questionId","status","type"],"ownershipFilter":"t.actor_account_id=REQUEST_ACCOUNT"},{"key":"ownedMediaAssets","dataClass":"MEDIA_OBJECTS","fields":["byteSize","bytesIncluded","conversationId","createdAt","height","id","profileId","scope","selected","state","width"],"ownershipFilter":"t.account_id=REQUEST_ACCOUNT"},{"key":"testAdmission","dataClass":"AUDIT_SECURITY_LOGS","fields":["admittedAt","retiredAt"],"ownershipFilter":"t.account_id=REQUEST_ACCOUNT"},{"key":"testAllocations","dataClass":"AUDIT_SECURITY_LOGS","fields":["allocatedMaximumMicrousd","createdAt","kind","measuredProviderCharge"],"ownershipFilter":"t.account_id=REQUEST_ACCOUNT"},{"key":"closureRequests","dataClass":"COMMAND_LEDGERS","fields":["closedAt","id","preparedAt","requestedAt","revision","state"],"ownershipFilter":"t.account_id=REQUEST_ACCOUNT"},{"key":"closureExecution","dataClass":"COMMAND_LEDGERS","fields":["closedAt","requestId","requestedAt","state"],"ownershipFilter":"t.account_id=REQUEST_ACCOUNT"},{"key":"closureActions","dataClass":"COMMAND_LEDGERS","fields":["dispatchedAt","evidence","kind","state","verifiedAt"],"ownershipFilter":"t.account_id=REQUEST_ACCOUNT"}]'::jsonb; $fn$;
create or replace function private.data_export_snapshot(p_account_id uuid,p_receipt_id uuid,p_binding jsonb,p_cutoff timestamptz) returns text language sql stable security definer set search_path=pg_catalog as $fn$
 with configured as (select value as config from jsonb_array_elements(p_binding#>'{delivery,datasets}')),
 owned_rows as (select 'account' as key,jsonb_build_object('id',t.id,'email',t.email,'fullName',t.full_name,'city',t.city,'phone',t.phone,'activeMode',t.active_mode,'createdAt',t.created_at) as value from public.app_accounts t where t.id=p_account_id
union all
select 'profiles' as key,jsonb_build_object('id',t.id,'kind',t.kind,'displayName',t.display_name,'city',t.city,'headline',t.headline,'bio',t.bio,'status',t.profile_status,'skills',t.skills,'operatingCountryCode',t.operating_country_code) as value from public.app_profiles t where t.account_id=p_account_id
union all
select 'availabilityWindows' as key,jsonb_build_object('id',t.id,'profileId',t.profile_id,'startsAt',t.starts_at,'endsAt',t.ends_at,'state',t.availability_state,'label',t.label) as value from public.profile_availability_windows t join public.app_profiles p on p.id=t.profile_id where p.account_id=p_account_id
union all
select 'availabilityRules' as key,jsonb_build_object('id',t.id,'profileId',t.profile_id,'weekdays',t.weekdays,'startTime',t.start_time,'endTime',t.end_time,'startsOn',t.starts_on,'endsOn',t.ends_on,'active',t.active,'label',t.label) as value from public.profile_availability_rules t join public.app_profiles p on p.id=t.profile_id where p.account_id=p_account_id
union all
select 'calendar' as key,jsonb_build_object('agreementId',t.agreement_id,'startsAt',t.starts_at,'endsAt',t.ends_at,'state',t.state) as value from private.worker_calendar_events t where t.worker_account_id=p_account_id
union all
select 'needs' as key,jsonb_build_object('id',t.id,'title',t.title,'description',t.description,'status',t.status,'revision',t.revision,'countryCode',t.task_country_code,'timezone',t.task_timezone,'executionMode',t.execution_location_mode,'startsAt',t.starts_at,'endsAt',t.ends_at,'requiredSlots',t.required_slots) as value from public.needs t where t.requester_account_id=p_account_id
union all
select 'needPrivate' as key,jsonb_build_object('needId',t.need_id,'exactAddress',t.exact_address,'accessNotes',t.access_notes,'latitude',t.exact_lat,'longitude',t.exact_lng,'resolvedPoints',coalesce((select jsonb_agg(jsonb_build_object('slot',v->'slot','latitudeE6',v->'latitudeE6','longitudeE6',v->'longitudeE6','address',v->'address','accessNotes',v->'accessNotes') order by v->>'slot') from jsonb_array_elements(t.resolved_location#>'{value,points}') v),'[]'::jsonb)) as value from public.need_sensitive t join public.needs n on n.id=t.need_id where n.requester_account_id=p_account_id
union all
select 'responses' as key,jsonb_build_object('id',t.id,'needId',t.need_id,'kind',t.response_kind,'status',t.status,'needRevision',t.submitted_against_need_revision,'priceRsd',t.price_rsd,'coveredSlots',t.covered_slots,'scopeNote',t.scope_note,'message',t.bounded_message,'createdAt',t.created_at) as value from public.marketplace_responses t where t.worker_account_id=p_account_id
union all
select 'ownQuestions' as key,jsonb_build_object('id',t.id,'needId',t.need_id,'question',t.question_text,'status',t.status,'createdAt',t.created_at) as value from private.preselection_qa_questions t where t.asker_account_id=p_account_id
union all
select 'ownAnswers' as key,jsonb_build_object('id',t.id,'questionId',t.question_id,'version',t.answer_version,'answer',t.answer_text,'createdAt',t.created_at) as value from private.preselection_qa_answer_versions t where t.answered_by_account_id=p_account_id
union all
select 'agreements' as key,jsonb_build_object('id',t.id,'needId',t.need_id,'status',t.status,'currentVersion',t.current_version,'createdAt',t.created_at) as value from public.agreements t where t.requester_account_id=p_account_id or t.worker_account_id=p_account_id
union all
select 'ownAgreementMessages' as key,jsonb_build_object('id',t.id,'agreementId',t.agreement_id,'body',t.body,'createdAt',t.created_at) as value from public.agreement_messages t join public.agreements a on a.id=t.agreement_id where t.sender_account_id=p_account_id and (a.requester_account_id=p_account_id or a.worker_account_id=p_account_id)
union all
select 'consent' as key,jsonb_build_object('id',t.id,'termsVersion',t.terms_version_label,'termsSha256',t.terms_content_sha256,'privacyVersion',t.privacy_version_label,'privacySha256',t.privacy_content_sha256,'acceptedAt',t.accepted_at) as value from public.account_legal_acceptance_events t where t.account_id=p_account_id
union all
select 'notifications' as key,jsonb_build_object('id',t.id,'role',t.recipient_role,'channel',t.channel,'state',t.state,'title',t.title,'body',t.body,'createdAt',t.created_at,'readAt',t.read_at) as value from public.notification_deliveries t where t.recipient_user_id=p_account_id
union all
select 'aiMessages' as key,jsonb_build_object('id',t.id,'conversationId',t.conversation_id,'role',t.role,'content',t.body,'createdAt',t.created_at) as value from public.ai_messages t join public.ai_conversations c on c.id=t.conversation_id where t.account_id=p_account_id and c.account_id=p_account_id
union all
select 'mediaMetadata' as key,jsonb_build_object('name',t.name,'createdAt',t.created_at,'bytesIncluded',false) as value from storage.objects t where t.bucket_id='profile-media' and split_part(t.name,'/',1)=p_account_id::text
union all
select 'exportRequests' as key,jsonb_build_object('id',t.id,'kind',t.request_kind,'status',t.status,'requestedAt',t.requested_at,'completedAt',t.completed_at) as value from public.data_export_requests t where t.account_id=p_account_id
union all
select 'ownAudit' as key,jsonb_build_object('id',t.id,'eventType',t.event_type,'entityType',t.entity_type,'entityId',t.entity_id,'createdAt',t.created_at) as value from private.marketplace_audit_log t where t.actor_user_id=p_account_id
union all
select 'ownAgreementReviews' as key,jsonb_build_object('id',t.id,'agreementId',t.agreement_id,'rating',t.rating,'tags',t.tags,'createdAt',t.created_at) as value from private.agreement_reviews t join public.agreements a on a.id=t.agreement_id where t.reviewer_account_id=p_account_id and (a.requester_account_id=p_account_id or a.worker_account_id=p_account_id)
union all
select 'ownSafetyReports' as key,jsonb_build_object('id',t.id,'needId',t.need_id,'agreementId',t.agreement_id,'category',t.category,'reason',t.reason,'narrative',t.narrative,'status',t.status,'createdAt',t.created_at) as value from private.safety_reports t where t.reporter_account_id=p_account_id
union all
select 'ownBlocks' as key,jsonb_build_object('targetAccountId',t.blocked_account_id,'active',t.active,'revision',t.revision,'updatedAt',t.updated_at) as value from private.account_blocks t where t.blocker_account_id=p_account_id
union all
select 'workerAiDrafts' as key,jsonb_build_object('conversationId',t.conversation_id,'profileId',t.profile_id,'revision',t.revision,'safety',t.safety,'profile',private.data_export_worker_candidate_v5(t.candidate),'createdAt',t.created_at) as value from private.worker_ai_sessions t join public.ai_conversations c on c.id=t.conversation_id where t.account_id=p_account_id and c.account_id=p_account_id
union all
select 'workerAiReviews' as key,jsonb_build_object('id',t.id,'conversationId',t.conversation_id,'revision',t.revision,'activate',private.data_export_scalar_v5(t.envelope->'activate','boolean'),'profile',private.data_export_worker_candidate_v5(t.envelope->'profile'),'createdAt',t.created_at) as value from private.worker_ai_reviews t join public.ai_conversations c on c.id=t.conversation_id where t.account_id=p_account_id and c.account_id=p_account_id
union all
select 'taskAiReviews' as key,jsonb_build_object('id',t.id,'conversationId',t.conversation_id,'draftId',private.data_export_scalar_v5(t.envelope->'draftId','string'),'draftRevision',private.data_export_scalar_v5(t.envelope->'draftRevision','number'),'responseDeadline',private.data_export_scalar_v5(t.envelope->'responseDeadline','string'),'publicFacts',private.data_export_task_facts_v5(t.envelope->'publicProjection'),'privateFacts',private.data_export_task_facts_v5(t.envelope->'ownerPrivateProjection'),'createdAt',t.created_at) as value from private.ai_task_reviews t join public.ai_conversations c on c.id=t.conversation_id where t.account_id=p_account_id and c.account_id=p_account_id
union all
select 'taskAiFacts' as key,jsonb_build_object('id',t.id,'conversationId',t.conversation_id,'facts',private.data_export_task_facts_v5(jsonb_build_array(jsonb_build_object('key',t.fact_key,'value',t.fact_value,'displayValue',t.display_value,'status',t.status)))) as value from public.ai_structured_facts t join public.ai_conversations c on c.id=t.conversation_id where c.account_id=p_account_id
union all
select 'workerAiTurns' as key,jsonb_build_object('id',t.turn_id,'conversationId',t.conversation_id,'state',t.state,'createdAt',t.created_at) as value from private.worker_ai_turns t where t.account_id=p_account_id
union all
select 'workerAiSaves' as key,jsonb_build_object('reviewId',t.review_id,'createdAt',t.created_at) as value from private.worker_ai_saves t where t.account_id=p_account_id
union all
select 'taskReviewCommands' as key,jsonb_build_object('reviewId',t.review_id,'needId',t.need_id,'needRevision',t.need_revision,'state',t.state,'createdAt',t.created_at) as value from private.ai_task_review_commands t where t.account_id=p_account_id
union all
select 'taskAiTurns' as key,jsonb_build_object('id',t.turn_id,'conversationId',t.conversation_id,'state',t.state,'cancelledAt',t.cancelled_at,'createdAt',t.created_at) as value from private.ai_need_turn_commands t where t.account_id=p_account_id
union all
select 'qaClassifications' as key,jsonb_build_object('id',t.id,'needId',t.need_id,'needRevision',t.need_revision,'questionId',t.question_id,'type',t.command_type,'state',t.state,'outcome',t.outcome,'materiality',t.materiality,'createdAt',t.created_at) as value from private.qa_ai_commands t where t.account_id=p_account_id
union all
select 'qaCommands' as key,jsonb_build_object('type',t.command_type,'questionId',private.data_export_scalar_v5(t.result->'questionId','string'),'status',private.data_export_scalar_v5(t.result->'status','string'),'createdAt',t.created_at) as value from private.preselection_qa_commands t where t.actor_account_id=p_account_id
union all
select 'ownedMediaAssets' as key,jsonb_build_object('id',t.id,'scope',t.scope,'conversationId',t.conversation_id,'profileId',t.profile_id,'state',t.state,'selected',t.selected,'width',t.width,'height',t.height,'byteSize',t.byte_size,'bytesIncluded',false,'createdAt',t.created_at) as value from private.owned_media_assets t where t.account_id=p_account_id
union all
select 'testAdmission' as key,jsonb_build_object('admittedAt',t.admitted_at,'retiredAt',t.retired_at) as value from private.ai_test_accounts_v5 t where t.account_id=p_account_id
union all
select 'testAllocations' as key,jsonb_build_object('kind',t.kind,'allocatedMaximumMicrousd',t.max_cost_microusd,'measuredProviderCharge',false,'createdAt',t.created_at) as value from private.ai_test_reservations_v5 t where t.account_id=p_account_id
union all
select 'closureRequests' as key,jsonb_build_object('id',t.id,'state',t.state,'revision',t.revision,'requestedAt',t.requested_at,'preparedAt',t.prepared_at,'closedAt',t.closed_at) as value from private.account_closure_requests t where t.account_id=p_account_id
union all
select 'closureExecution' as key,jsonb_build_object('requestId',t.request_id,'state',t.state,'requestedAt',t.requested_at,'closedAt',t.closed_at) as value from private.closure_executions_v5 t where t.account_id=p_account_id
union all
select 'closureActions' as key,jsonb_build_object('kind',t.kind,'state',t.state,'dispatchedAt',t.dispatched_at,'verifiedAt',t.verified_at,'evidence',t.evidence) as value from private.closure_actions_v5 t where t.account_id=p_account_id),
 projected as (select r.key,(select jsonb_object_agg(field,r.value->field order by field) from jsonb_array_elements_text(c.config->'fields') field) as value
 from owned_rows r join configured c on c.config->>'key'=r.key and c.config->>'mode'='INCLUDE'),
 grouped as (select c.config->>'key' as key,coalesce(jsonb_agg(p.value order by p.value::text) filter(where p.key is not null),'[]'::jsonb) as rows
 from configured c left join projected p on p.key=c.config->>'key' where c.config->>'mode'='INCLUDE' group by c.config->>'key')
 select jsonb_build_object('schemaVersion','USKOCI_DATA_EXPORT_V2','receiptId',p_receipt_id,'accountId',p_account_id,'snapshotAt',p_cutoff,
 'projectionVersion','OWN_ACCOUNT_V5_1','policy',jsonb_build_object('policyId',p_binding->'policyId','policyVersion',p_binding->'policyVersion','privacyDocumentId',p_binding->'privacyDocumentId','privacyContentSha256',p_binding->'privacyContentSha256','sha256',p_binding->'sha256'),
 'datasets',(select jsonb_object_agg(key,rows order by key) from grouped),
 'datasetCounts',(select jsonb_object_agg(key,jsonb_array_length(rows) order by key) from grouped),
 'reviewedOmissions',(select coalesce(jsonb_agg(config order by config->>'key'),'[]'::jsonb) from configured where config->>'mode'='EXCLUDE'))::text
 where exists(select 1 from public.app_accounts where id=p_account_id);
$fn$;

create function private.data_export_projection_sha_v5() returns text language sql stable security definer set search_path=pg_catalog as $f$ select encode(extensions.digest(convert_to(string_agg(signature||':'||md5(replace(p.prosrc,E'\r\n',E'\n')),E'\n' order by signature),'UTF8'),'sha256'),'hex') from unnest(array['private.data_export_dataset_catalog()','private.data_export_snapshot(uuid,uuid,jsonb,timestamptz)','private.data_export_scalar_v5(jsonb,text)','private.data_export_array_v5(jsonb,text)','private.data_export_worker_candidate_v5(jsonb)','private.data_export_task_facts_v5(jsonb)']) signature join pg_proc p on p.oid=to_regprocedure(signature) having count(*)=6 $f$;
revoke all on function private.data_export_projection_sha_v5() from public,anon,authenticated,service_role;
create or replace function private.data_export_policy_binding() returns jsonb language plpgsql stable security definer set search_path=pg_catalog as $fn$
declare p private.retention_policy_sets; m jsonb; d jsonb; c jsonb; seen text[]:='{}'; f jsonb; fields text[]; refs jsonb; privacy private.legal_document_versions; v_now timestamptz:=clock_timestamp();
begin
 select * into p from private.retention_policy_sets where retired_at is null and effective_at<=v_now;
 if not found then return null; end if;
 m:=p.export_delivery;
 if jsonb_typeof(m) is distinct from 'object' or m-ARRAY['schemaVersion','projectionVersion','projectionSha256','privacyDocumentId','privacyContentSha256','contentSha256','artifactLifetimeSeconds','snapshotLifetimeSeconds','downloadLifetimeSeconds','cleanupMode','snapshotCleanupMode','datasets']<>'{}'::jsonb
 or not(m ?& ARRAY['schemaVersion','projectionVersion','projectionSha256','privacyDocumentId','privacyContentSha256','contentSha256','artifactLifetimeSeconds','snapshotLifetimeSeconds','downloadLifetimeSeconds','cleanupMode','snapshotCleanupMode','datasets'])
 or m->>'schemaVersion' is distinct from 'USKOCI_EXPORT_DELIVERY_V2' or m->>'projectionVersion' is distinct from 'OWN_ACCOUNT_V5_1'
 or jsonb_typeof(m->'projectionSha256') is distinct from 'string' or coalesce(m->>'projectionSha256','')!~'^[a-f0-9]{64}$'
 or m->>'projectionSha256' is distinct from private.data_export_projection_sha_v5()
 or m->>'cleanupMode' is distinct from 'DELETE_EXPORT_COPY' or m->>'snapshotCleanupMode' is distinct from 'DELETE_TEMP_SNAPSHOT'
 or coalesce(m->>'privacyDocumentId','')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
 or coalesce(m->>'privacyContentSha256','')!~'^[0-9a-f]{64}$' or coalesce(m->>'contentSha256','')!~'^[0-9a-f]{64}$'
 or m->>'contentSha256' is distinct from encode(extensions.digest(convert_to((m-'contentSha256')::text,'UTF8'),'sha256'),'hex') then return null; end if;
 foreach fields slice 1 in array ARRAY[ARRAY['artifactLifetimeSeconds','2592000'],ARRAY['snapshotLifetimeSeconds','2592000'],ARRAY['downloadLifetimeSeconds','900']] loop
   if jsonb_typeof(m->fields[1]) is distinct from 'number' or (m->>fields[1])!~'^[1-9][0-9]*$' or (m->>fields[1])::numeric>(fields[2])::numeric then return null; end if;
 end loop;
 if (m->>'downloadLifetimeSeconds')::integer>(m->>'artifactLifetimeSeconds')::integer then return null; end if;
 select * into privacy from private.legal_document_versions where id=(m->>'privacyDocumentId')::uuid and document_kind='PRIVACY' and is_active and retired_at is null and effective_at<=v_now and content_sha256=m->>'privacyContentSha256';
 if not found then return null; end if;
 if exists(select 1 from private.retention_data_classes dc where dc.active and dc.required and (not exists(select 1 from private.retention_policy_rules r where r.policy_id=p.id and r.data_class=dc.code) or not exists(select 1 from jsonb_array_elements(private.data_export_dataset_catalog()) v where v->>'dataClass'=dc.code))) then return null; end if;
 if jsonb_typeof(m->'datasets') is distinct from 'array' or jsonb_array_length(m->'datasets')<>37 then return null; end if;
 for d in select value from jsonb_array_elements(m->'datasets') loop
   if jsonb_typeof(d) is distinct from 'object' or jsonb_typeof(d->'key') is distinct from 'string' or d->>'key'=any(seen) then return null; end if;
   select value into c from jsonb_array_elements(private.data_export_dataset_catalog()) where value->>'key'=d->>'key';
   if not found then return null; end if;seen:=array_append(seen,d->>'key');
   if d->>'mode'='EXCLUDE' then
     if d-ARRAY['key','mode','reasonCode']<>'{}'::jsonb or not(d ?& ARRAY['key','mode','reasonCode']) or jsonb_typeof(d->'reasonCode') is distinct from 'string' or d->>'reasonCode'!~'^[A-Z][A-Z0-9_]{0,63}$' or d->>'key'='account' then return null; end if;
   elsif d->>'mode'='INCLUDE' then
     if d-ARRAY['key','mode','fields']<>'{}'::jsonb or not(d ?& ARRAY['key','mode','fields']) or jsonb_typeof(d->'fields') is distinct from 'array' then return null; end if;
     if jsonb_array_length(d->'fields')<1 or jsonb_array_length(d->'fields')>64 then return null; end if;fields:='{}';
     for f in select value from jsonb_array_elements(d->'fields') loop
       if jsonb_typeof(f)<>'string' or not((c->'fields') ? (f#>>'{}')) or f#>>'{}'=any(fields) then return null; end if; fields:=array_append(fields,f#>>'{}');
     end loop;
     if d->>'key'='account' and not('id'=any(fields)) then return null; end if;
     if d->>'key' in('mediaMetadata','ownedMediaAssets') and not('bytesIncluded'=any(fields)) then return null; end if;
   else return null; end if;
 end loop;
 select coalesce(jsonb_agg(to_jsonb(r) order by data_class),'[]'::jsonb) into refs from private.retention_policy_rules r where policy_id=p.id;
 return jsonb_build_object('policyId',p.id,'policyVersion',p.policy_version,'privacyDocumentId',privacy.id,'privacyContentSha256',privacy.content_sha256,'delivery',m,
 'sha256',encode(extensions.digest(convert_to(jsonb_build_object('policy',to_jsonb(p),'rules',refs,'privacy',to_jsonb(privacy),'catalog',private.data_export_dataset_catalog())::text,'UTF8'),'sha256'),'hex'));
exception when data_exception then return null;
end $fn$;

notify pgrst,'reload schema';
commit;
